//
//  fw_table.h — plain lookup table over the embedded firmware blobs in
//  $(BUILD)/firmware/fw_*.c (generated by tools/embed-firmware.py). No allocation, no
//  STL, no exceptions/RTTI — kernel-safe, C++17 aggregate data only.
//
//  Implementation: src/amd/fw_table.cpp (see that file for why — the
//  Makefile builds src/amd/*.cpp, but NOT src/fw/*.cpp, so
//  a same-directory fw_table.cpp would silently never be compiled).
//
#pragma once

#include <stdint.h>
#include <stddef.h>

namespace amdgpu {

struct AsicInfo;   // ../amd/amdgpu_asic.h

// Stable index space for every firmware blob the gfx1201 (Navi 48) and
// gfx1200 (Navi 44) bring-up ladders can name. Not every id has embedded data on this card:
// GC_MES / GC_MES1 (legacy split MES packaging — superseded here by
// GC_UNI_MES) and GC_TOC (only loaded for psp_14_0_5, not psp_14_0_3)
// have a table entry with data=nullptr, size=0. Always check
// FwBlob::data before use. See BUILDING.md for firmware provenance.
enum class FwId : uint32_t {
    PSP_SOS,
    PSP_TA,
    GC_IMU,
    GC_PFP,
    GC_ME,
    GC_MEC,
    GC_MES,
    GC_MES1,
    GC_UNI_MES,
    GC_RLC,
    GC_TOC,
    SMU,
    SDMA,
    DCN_DMUB,
    Count
};

struct FwBlob {
    const uint8_t *data;  // nullptr if this id has no embedded blob
    size_t size;          // 0 if this id has no embedded blob
    const char *name;     // bare blob name, e.g. "gc_12_0_1_imu"
    FwId id;
};

// Both lookups answer for the chip selected with asic_select() (amdgpu_asic.h;
// nullptr when no chip is selected or the chip id is unknown).
// Returns the table entry for `id`, or nullptr if `id` is out of range
// (i.e. >= FwId::Count) or no chip is selected. For a selected chip, in-range
// ids always return an entry — check ->data for blobs with no embedded bytes
// (see FwId comment above).
const FwBlob *fw_get(FwId id);

// Looks up by bare name (e.g. "smu_14_0_3"); returns nullptr if not found.
// Also nullptr when no chip is selected.
const FwBlob *fw_find_by_name(const char *name);

// True when every blob `asic` needs (all ids but GC_MES / GC_MES1 / GC_TOC)
// is embedded with a non-zero size. False for a chip the kext was built
// without (its blobs are the Makefile's zero-length stubs), for nullptr,
// and for unknown chip ids.
bool fw_chip_complete(const AsicInfo *asic);

} // namespace amdgpu
